17	import {
18	  CatalogScmEvent,
19	  CatalogScmEventsService,
20	  CatalogScmEventsServiceSubscriber,
21	} from './types';
22	
23	/**
24	 * The default implementation of the {@link CatalogScmEventsService}/{@link catalogScmEventsServiceRef}.
25	 *
26	 * @internal
27	 * @remarks
28	 *
29	 * This implementation is in-memory, which requires the producers and consumer
30	 * (the catalog backend) to be deployed together.
31	 */
32	export class DefaultCatalogScmEventsService implements CatalogScmEventsService {
33	  readonly #subscribers: Set<CatalogScmEventsServiceSubscriber>;
34	
35	  constructor() {
36	    this.#subscribers = new Set();
37	  }
38	
39	  subscribe(subscriber: CatalogScmEventsServiceSubscriber): {
40	    unsubscribe: () => void;
41	  } {
42	    this.#subscribers.add(subscriber);
43	    return {
44	      unsubscribe: () => {
45	        this.#subscribers.delete(subscriber);
46	      },
47	    };
48	  }
49	
50	  async publish(events: CatalogScmEvent[]): Promise<void> {
51	    await Promise.all(
52	      Array.from(this.#subscribers).map(async subscriber => {
53	        try {
54	          await subscriber.onEvents(events);
55	        } catch (error) {
56	          // The subscribers are expected to handle errors themselves.
57	        }
58	      }),
59	    );
60	  }
61	}
