150	  async getLocation(id: string): Promise<Location> {
151	    const items = await this.db<DbLocationsRow>('locations')
152	      .where({ id })
153	      .select();
154	
155	    if (!items.length) {
156	      throw new NotFoundError(`Found no location with ID ${id}`);
157	    }
158	    return items[0];
