17	import { Span, SpanOptions, SpanStatusCode, Tracer } from '@opentelemetry/api';
18	import { Entity } from '@backstage/catalog-model';
19	
20	export const TRACER_ID = 'backstage-plugin-catalog-backend';
21	
22	function setAttributeIfDefined(span: Span, attribute: string, value?: string) {
23	  if (value !== null && value !== undefined) {
24	    span.setAttribute(attribute, value);
25	  }
26	}
27	
28	export function addEntityAttributes(span: Span, entity: Entity) {
29	  setAttributeIfDefined(span, 'backstage.entity.apiVersion', entity.apiVersion);
30	  setAttributeIfDefined(span, 'backstage.entity.kind', entity.kind);
31	  setAttributeIfDefined(
32	    span,
33	    'backstage.entity.metadata.namespace',
34	    entity.metadata?.namespace,
35	  );
36	  setAttributeIfDefined(
37	    span,
38	    'backstage.entity.metadata.name',
39	    entity.metadata?.name,
40	  );
41	}
42	
43	// Adapted from https://github.com/open-telemetry/opentelemetry-js/blob/359fbcc40a859057a02b14e84599eac399b8dba7/api/src/trace/SugaredTracer.ts
44	// While waiting for something like https://github.com/open-telemetry/opentelemetry-js/pull/3317 to land upstream
45	
46	const onException = (e: Error, span: Span) => {
47	  span.recordException(e);
48	  span.setStatus({
49	    code: SpanStatusCode.ERROR,
50	  });
51	};
52	
53	function isPromiseLike<T, S>(obj: PromiseLike<T> | S): obj is PromiseLike<T> {
54	  return (
55	    !!obj &&
56	    (typeof obj === 'object' || typeof obj === 'function') &&
57	    'then' in obj &&
58	    typeof obj.then === 'function'
59	  );
60	}
61	
62	function handleFn<F extends (span: Span) => ReturnType<F>>(
63	  span: Span,
64	  fn: F,
65	): ReturnType<F> {
66	  try {
67	    const ret = fn(span);
68	
69	    // if fn is an async function attach a recordException and spanEnd callback to the promise
70	    if (isPromiseLike(ret)) {
71	      ret.then(
72	        () => {
73	          span.end();
74	        },
75	        e => {
76	          onException(e, span);
77	          span.end();
78	        },
79	      );
80	    } else {
81	      span.end();
82	    }
83	
84	    return ret;
85	  } catch (e) {
86	    onException(e, span);
87	    span.end();
88	    throw e;
89	  }
90	}
91	
92	export function withActiveSpan<F extends (span: Span) => ReturnType<F>>(
93	  tracer: Tracer,
94	  name: string,
95	  fn: F,
96	  spanOptions: SpanOptions = {},
97	): ReturnType<F> {
98	  return tracer.startActiveSpan(name, spanOptions, (span: Span) => {
99	    return handleFn(span, fn);
100	  });
101	}
